    pub fn name(__cp_self: @This()) []const u8 { return @tagName(__cp_self); }

pub fn message(self: CompileResultReason) []const u8 {
            return (switch (self) {
.no_entry_point => "No entry point found for compilation",
.no_output_files => "No output files to bundle",
});
    }
};

pub const CompileResultError = union(enum) {
    message: []const u8,
    reason: CompileResultReason,
    pub fn has(s: []const u8) bool { if (comptime @typeInfo(@This()).@"union".tag_type) |TagType| { return std.meta.stringToEnum(TagType, s) != null; } return false; }
    pub fn name(self: @This()) []const u8 { return @tagName(self); }

pub fn slice(self: CompileResultError) []const u8 {
            return (switch (self) {
.message => |msg| msg,
.reason => |r| r.message(),
});
    }
    
    pub const Reason = CompileResultReason;
};

pub const StandaloneCompileResult = union(enum) {
    success: void,
    err: CompileResultError,
    pub fn has(s: []const u8) bool { if (comptime @typeInfo(@This()).@"union".tag_type) |TagType| { return std.meta.stringToEnum(TagType, s) != null; } return false; }
    pub fn name(self: @This()) []const u8 { return @tagName(self); }

pub fn fail(reason: CompileResultReason) StandaloneCompileResult {
            return .{ .err = .{ .reason = reason } };
    }

pub fn failFmt(comptime fmt: []const u8, args: anytype) StandaloneCompileResult {
            return .{ .err = .{ .message = bun.handleOom(std.fmt.allocPrint(bun.default_allocator, fmt, args)) } };
    }

pub fn deinit(self: StandaloneCompileResult) void {
            switch (self) {
.success => {

},
.err => |e| {
switch (e) {
.message => |msg| {
_ = bun.default_allocator.free(msg);
},
.reason => {

},
}
},
}
    }
    
    pub const Error = CompileResultError;
};

