pub const Macho = struct {

pub fn getData() ?[]const u8 {
            {
                if (Bun__getStandaloneModuleGraphMachoLength()) |slice_ptr| {
                    _ = &slice_ptr;
                    const len = std.mem.bytesToValue(u64, slice_ptr[0..8]);
                    if ((len < 8)) {
                        return null;
                    }
                    const data_offset = @sizeOf(u64);
                    return slice_ptr[data_offset..][0..len];
                }
            }
            return null;
    }
};

pub const PE = struct {

pub fn getData() ?[]const u8 {
            {
                const len = Bun__getStandaloneModuleGraphPELength();
                if ((len == 0)) {
                    return null;
                }
                const data_ptr_opt = Bun__getStandaloneModuleGraphPEData();
                if ((data_ptr_opt == null)) {
                    return null;
                }
                const data_ptr = data_ptr_opt.?;
                return data_ptr[0..len];
            }
    }
};

pub const ELF = struct {

pub fn getData() ?[]const u8 {
            {
                const vaddr_ptr_opt = Bun__getStandaloneModuleGraphELFVaddr();
                if ((vaddr_ptr_opt == null)) {
                    return null;
                }
                const vaddr_ptr = vaddr_ptr_opt.?;
                const vaddr = std.mem.bytesToValue(u64, vaddr_ptr[0..8]);
                if ((vaddr == 0)) {
                    return null;
                }
                const target: [*]const u8 = @ptrFromInt(vaddr);
                const payload_len = std.mem.readInt(u64, target[0..8], .little);
                if ((payload_len < 8)) {
                    return null;
                }
                return target[8..][0..payload_len];
            }
    }
};

pub const SerializedSourceMapHeader = extern struct {
    source_files_count: u32,
    map_bytes_length: u32,
};

pub const SerializedSourceMapLoaded = struct {
    map: StandaloneSerializedSourceMap,
    decompressed_files: []OptMutBytes,

pub fn sourceFileContents(self: *SerializedSourceMapLoaded, index: usize) ?[]const u8 {
            if (self.decompressed_files[@as(usize, @intCast(index))]) |decompressed| {
                _ = &decompressed;
                return (if ((decompressed.len == 0)) null else decompressed);
            }
            const compressed_file = self.map.compressedSourceFileAt(index).slice(self.map.bytes);
            const size = bun.zstd.getDecompressedSize(compressed_file);
            const bytes = bun.handleOom(bun.default_allocator.alloc(u8, size));
            const result = bun.zstd.decompress(bytes, compressed_file);
            if ((result == .err)) {
                _ = bun.Output.warn("Source map decompression error: {s}", .{ result.err });
                _ = bun.default_allocator.free(bytes);
                self.decompressed_files[cp_cast_int(usize, index)] = "";
                return null;
            }
            const data = bytes[0..result.success];
            self.decompressed_files[cp_cast_int(usize, index)] = data;
            return data;
    }
};

pub const StandaloneSerializedSourceMap = struct {
    bytes: []const u8,

pub fn header(self: StandaloneSerializedSourceMap) Header {
            return std.mem.bytesToValue(Header, self.bytes[0..@sizeOf(Header)]);
    }

pub fn mappingBlob(self: *const StandaloneSerializedSourceMap) ?[]const u8 {
            if ((self.bytes.len < @sizeOf(Header))) {
                return null;
            }
            const head = self.header();
            const start = (@sizeOf(Header) + ((head.source_files_count * @sizeOf(StringPointer)) * 2));
